#include <vector>

class Solution {
public:
    std::vector<int> findSmallestSetOfVertices(int n, std::vector<std::vector<int>>& edges) {
        std::vector<bool> hasIncoming(n, false);
        for (const auto& e : edges) hasIncoming[e[1]] = true;
        std::vector<int> ans;
        for (int i = 0; i < n; ++i) {
            if (!hasIncoming[i]) ans.push_back(i);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public List<Integer> findSmallestSetOfVertices(int n, List<List<Integer>> edges) {
        boolean[] hasIncoming = new boolean[n];
        for (List<Integer> e : edges) {
            hasIncoming[e.get(1)] = true;
        }
        List<Integer> ans = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            if (!hasIncoming[i]) ans.add(i);
        }
        return ans;
    }
}

